static void source_pop(struct em_source *members)
{
	struct neocc_source_buffer *buffer = members->top;

	members->top = buffer->prev;
	if (buffer->fd > 0)
		close(buffer->fd);
	if (buffer->true_filename != buffer->filename)
		free(buffer->true_filename);
	free(buffer);
}

static int source_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	return R_P;
}

static int source_close(struct object *self, const struct vr *caller_context)
{
	struct em_source *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		while (members->top)
			source_pop(members);
	return R_P;
}

static int source_interact3(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_source *members = self->members;
	struct neocc_source_request request;
	struct neocc_source_result result;
	struct neocc_source_buffer *buffer;
	size_t size, name_length, i;

	if (action != NEOCC_AC3_SOURCE_PUSH) {
		SBO_OBJECT_INTERACT3;
	}
	if (output_quantity)
		*output_quantity = 0;
	if (!self->ref_count)
		return RN_INVALIDARG;
	if (!input_stream || quantity != sizeof(request) || !output_stream ||
	    capacity < sizeof(result) || !output_quantity)
		return RN_INVALIDARG;
	memcpy(&request, input_stream, sizeof(request));
	if (!request.name || request.fd < -1 ||
	    request.length > INT_MAX ||
	    request.length > SIZE_MAX - sizeof(*buffer) - 1)
		return RN_INVALIDARG;
	name_length = strlen(request.name);
	if (name_length >= sizeof(buffer->filename))
		return RN_INVALIDARG;
	size = request.length ? request.length : NEOCC_SOURCE_BUFFER_SIZE;
	buffer = calloc(1, sizeof(*buffer) + size + 1);
	if (!buffer)
		return R_N;
	buffer->buf_ptr = buffer->buffer;
	buffer->buf_end = buffer->buffer + request.length;
	*buffer->buf_end = NEOCC_SOURCE_EOB;
	memcpy(buffer->filename, request.name, name_length + 1);
	/* C and assembly diagnostics use the same spelling on both hosts. */
	for (i = 0; i < name_length; i++)
		if (buffer->filename[i] == '\\')
			buffer->filename[i] = '/';
	buffer->true_filename = buffer->filename;
	buffer->line_num = 1;
	buffer->ifdef_stack_ptr = request.ifdef_stack_ptr;
	buffer->prev_tok_flags = request.tok_flags;
	buffer->fd = request.fd;
	buffer->prev = members->top;
	members->top = buffer;
	result = (struct neocc_source_result){ buffer, 0, 0 };
	memcpy(output_stream, &result, sizeof(result));
	*output_quantity = sizeof(result);
	return R_P;
}

static int source_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_source *members = self->members;
	struct neocc_source_buffer *buffer = members->top;
	struct neocc_source_result result;

	if (action != NEOCC_AC1_SOURCE_POP) {
		SBO_OBJECT_INTERACT1;
	}
	if (output_quantity)
		*output_quantity = 0;
	if (!self->ref_count || !output_stream || capacity < sizeof(result) ||
	    !output_quantity)
		return RN_INVALIDARG;
	if (!buffer)
		return RO_VAINLY;
	result = (struct neocc_source_result){ buffer->prev,
		buffer->prev_tok_flags, buffer->fd > 0 ? buffer->line_num - 1 : 0 };
	source_pop(members);
	memcpy(output_stream, &result, sizeof(result));
	*output_quantity = sizeof(result);
	return R_P;
}

static int source_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_source *members = self->members;
	struct neocc_source_buffer *buffer = members->top;
	char *name;
	size_t length;

	if (action != NEOCC_AC0_SOURCE_SAVE_NAME) {
		SBO_OBJECT_INTERACT0;
	}
	if (!self->ref_count || !buffer)
		return RN_INVALIDARG;
	if (buffer->true_filename != buffer->filename)
		return R_P;
	length = strlen(buffer->filename) + 1;
	name = malloc(length);
	if (!name)
		return R_N;
	memcpy(name, buffer->filename, length);
	buffer->true_filename = name;
	return R_P;
}

