void tog_source(struct object *object)
{
	object->open = source_open;
	object->input = source_input;
	object->output = source_output;
	object->io_put = source_io_put;
	object->interact0 = source_interact0;
	object->interact1 = source_interact1;
	object->interact2 = source_interact2;
	object->interact3 = source_interact3;
	object->close = source_close;
}
